import math
import sys
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))
sys.path.insert(0, str(Path(__file__).resolve().parent))

import numpy as np  # noqa: E402

from nav_core_test import FOOT, H_TOP, build, check, results, wall  # noqa: E402
from src.nav_follower import route_controller  # noqa: E402
from src.nav_smooth import plan_route  # noqa: E402
from src.staging_source import _pose_controller  # noqa: E402
from src.task_config import NAV_CFG, STAGING_CFG, TASK_CFG  # noqa: E402

DT = 1.0 / 150.0
BENCH = {"id": "bench", "outline": [[-2.2, -0.8], [2.2, -0.8], [2.2, 0.8], [-2.2, 0.8]], "height_range": (0.0, 0.96), "found": "map"}
WALLS = [wall(10, -6.0, -6.0, 6.0, -5.92), wall(11, -6.0, 5.92, 6.0, 6.0), wall(12, -6.0, -6.0, -5.92, 6.0), wall(13, 5.92, -6.0, 6.0, 6.0)]
SPAWN = (TASK_CFG["spawn_xy"][0], TASK_CFG["spawn_xy"][1], TASK_CFG["spawn_yaw"])
APPROACH = (TASK_CFG["staging_xy"][0], TASK_CFG["staging_xy"][1] + TASK_CFG["staging_approach_back_m"], TASK_CFG["staging_yaw"])


def wrap(a):
    return (a + math.pi) % (2 * math.pi) - math.pi


def make(cfg, grid, fine, goal, obstacles_for_plan=None):
    cfg_s = STAGING_CFG
    final = _pose_controller(cfg_s, goal, cfg_s["drive_max_lin_vel"], cfg_s["drive_max_ang_vel"], cfg_s["drive_pos_tol"], cfg_s["drive_yaw_tol"], cfg_s["drive_pos_tol"], cfg_s["drive_yaw_tol"], cfg_s["drive_max_reapproach"])
    plan_fn = lambda x, y, yaw: plan_route(grid, fine, (x, y, yaw), goal, cfg)
    clearance = lambda x, y: float(grid.dist[min(max(grid.cell_of((x, y))[1], 0), grid.shape[0] - 1), min(max(grid.cell_of((x, y))[0], 0), grid.shape[1] - 1)] - grid.r_in)
    return route_controller(cfg, plan_fn, final, clearance, max_ang=cfg["rotate_to_heading_angular_vel"])


def drive(ctl, start, max_s=240.0, pushes=(), log=False):
    """Runs the controller on a unicycle that does exactly what it is told; pushes: [(time, dx, dy)] moves the base sideways."""
    x, y, yaw = start
    tw = (0.0, 0.0)
    ctl["reset"](x, y, yaw)
    pushes = list(pushes)
    t, status, vmax, amax, wmax, cmds = 0.0, "running", 0.0, 0.0, 0.0, []
    last_lin = 0.0
    while t < max_s:
        obs = {"base_pose": (x, y, yaw), "applied": {"twist": tw}}
        cmds, status = ctl["step"](obs, t, DT)
        if status != "running":
            break
        tw = cmds[0]["twist"]
        vmax, wmax = max(vmax, abs(tw[0])), max(wmax, abs(tw[1]))
        amax = max(amax, abs(tw[0] - last_lin) / DT)
        last_lin = tw[0]
        yaw += tw[1] * DT
        x += tw[0] * math.cos(yaw) * DT
        y += tw[0] * math.sin(yaw) * DT
        t += DT
        while pushes and t >= pushes[0][0]:
            _, dx, dy = pushes.pop(0)
            x, y = x + dx, y + dy
    return {"status": status, "t": t, "pose": (x, y, yaw), "vmax": vmax, "wmax": wmax, "amax": amax}


def main():
    print("1. the bench approach from the spawn")
    grid, fine = build([BENCH] + WALLS)
    cfg = dict(NAV_CFG)
    ctl = make(cfg, grid, fine, APPROACH)
    r = drive(ctl, SPAWN)
    S = ctl["S"]
    e_pos = math.hypot(r["pose"][0] - APPROACH[0], r["pose"][1] - APPROACH[1])
    e_yaw = abs(math.degrees(wrap(r["pose"][2] - APPROACH[2])))
    print(f"     arrival error {e_pos * 1000:.1f} mm, {e_yaw:.2f} deg after {r['t']:.1f} s; cross-track max {S['cross_track_max'] * 1000:.1f} mm; curvature used up to {S.get('max_curvature_used', 0):.2f} 1/m; "
          f"route {S['routes'][0]['length']:.2f} m, lead-in {S['routes'][0]['lead_in_m']}, lead-out {S['routes'][0]['lead_out_m']}; planning {S['plan_seconds']:.2f} s")
    check("it arrives", r["status"] == "arrived", r["status"] + " " + str(S["fail"]))
    check("the arrival is within 1 cm and 1 degree (the test's pass), reported above", e_pos <= 0.01 and e_yaw <= 1.0)
    check("the arrival is within the aim of 1 cm and 0.5 degrees unless the controller reported aim_missed", (e_pos <= 0.01 and e_yaw <= 0.5) or S["aim_missed"], f"aim_missed {S['aim_missed']}")
    check("the cross-track error stayed under the 5 cm tolerance and no replan was needed", S["cross_track_max"] < NAV_CFG["track_tol"] and S["replans"] == 0, f"{S['cross_track_max'] * 1000:.1f} mm, replans {S['replans']}")
    check("the speed and acceleration limits held (speed <= 0.30 m/s, yaw rate <= 0.40 rad/s, linear acceleration <= 0.16 m/s^2)", r["vmax"] <= 0.3 + 1e-9 and r["wmax"] <= 0.4 + 1e-9 and r["amax"] <= 0.16, f"v {r['vmax']:.3f} w {r['wmax']:.3f} a {r['amax']:.3f}")

    print("\n2. the curvature feed-forward against Nav2's plain pursuit (k_fb = 1)")
    cfg1 = dict(NAV_CFG, k_fb=1.0)
    ctl1 = make(cfg1, grid, fine, APPROACH)
    r1 = drive(ctl1, SPAWN)
    print(f"     k_fb 0.5: cross-track max {S['cross_track_max'] * 1000:.1f} mm, {r['t']:.1f} s; k_fb 1.0: cross-track max {ctl1['S']['cross_track_max'] * 1000:.1f} mm, {r1['t']:.1f} s")
    check("plain pursuit (k_fb 1) also arrives (the setting works both ways)", r1["status"] == "arrived")

    print("\n3. a sideways push of 8 cm: stop, replan from where it is, go on")
    ctl2 = make(cfg, grid, fine, APPROACH)
    r2 = drive(ctl2, SPAWN, pushes=[(14.0, 0.08, 0.0)])
    S2 = ctl2["S"]
    check("one replan, then it arrives within 1 cm and 1 degree", r2["status"] == "arrived" and S2["replans"] == 1 and math.hypot(r2["pose"][0] - APPROACH[0], r2["pose"][1] - APPROACH[1]) <= 0.01
          and abs(math.degrees(wrap(r2["pose"][2] - APPROACH[2]))) <= 1.0, f"{r2['status']} replans {S2['replans']} {S2['fail']}")

    print("\n4. pushes beyond the replan limit: a failure for the operator")
    ctl3 = make(cfg, grid, fine, APPROACH)
    r3 = drive(ctl3, SPAWN, pushes=[(12.0 + 8.0 * k, 0.09, 0.0) for k in range(6)])
    check("after max_replans (3) it stops with the reason, no further move", r3["status"] == "failed" and ctl3["S"]["fail_kind"] == "replans used up" and ctl3["S"]["replans"] == 4, f"{r3['status']} {ctl3['S']['fail_kind']} {ctl3['S']['replans']}")

    print("\n5. no path: the failure names the reason, nothing moves")
    closed = [wall(0, 1.0, 1.0, 4.0, 1.2), wall(1, 1.0, 4.0, 4.0, 4.2), wall(2, 1.0, 1.0, 1.2, 4.2), wall(3, 3.8, 1.0, 4.0, 4.2)]
    g4, f4 = build(closed)
    ctl4 = make(cfg, g4, f4, (2.5, 2.6, 0.0))
    r4 = drive(ctl4, (-2.0, 0.0, 0.0))
    check("no path: failed at once, kind \"no path\", the base did not move", r4["status"] == "failed" and ctl4["S"]["fail_kind"] == "no path" and r4["t"] == 0.0 and "no path" in ctl4["S"]["fail"], str(ctl4["S"]["fail"]))

    print("\n6. the default setting")
    check("NAV_CFG[\"follow\"] is False (today's DRIVE, the pipeline byte-identical)", NAV_CFG["follow"] is False)
    print(f"\n{sum(results)}/{len(results)} checks passed")
    return all(results)


